1	#!/usr/bin/env node
2	// Prov Guard —— 软件供应链证明与完整性校验工具（零依赖，Node >= 18）。
3	//
4	// 子命令：
5	//   keygen   --key-dir <dir> [--name <prefix>]
6	//   generate --artifact <path> --key <private-key> --out <dir>
7	//   verify   --artifact <path> --proof <file> --signature <file> --key <public-key>
8	//            [--sbom <file> --sbom-signature <file>] [--policy <policy.json>]
9	//
10	// 所有输出均为 UTF-8；成功结果写 stdout，错误结果写 stderr。
11	
12	import {
13	  createHash,
14	  createPrivateKey,
15	  createPublicKey,
16	  generateKeyPairSync,
17	  sign as cryptoSign,
18	  verify as cryptoVerify,
19	} from 'node:crypto';
20	import { constants as fsConstants, readFileSync, realpathSync } from 'node:fs';
21	import { access, mkdir, readdir, readFile, realpath, rename, rm, stat, writeFile } from 'node:fs/promises';
22	import { basename, dirname, isAbsolute, join, relative, resolve, sep } from 'node:path';
23	import { fileURLToPath } from 'node:url';
24	
25	export const PROOF_VERSION = '1.0';
26	
27	// ---------------------------------------------------------------------------
28	// 错误类型：携带机器可读错误码，CLI 边界统一转换为非零退出。
29	// ---------------------------------------------------------------------------
30	
31	export const ERROR_CODES = Object.freeze({
32	  INPUT_NOT_FOUND: 'INPUT_NOT_FOUND',
33	  PERMISSION_DENIED: 'PERMISSION_DENIED',
34	  PROOF_INVALID: 'PROOF_INVALID',
35	  SIGNATURE_INVALID: 'SIGNATURE_INVALID',
36	  KEY_NOT_FOUND: 'KEY_NOT_FOUND',
37	  INTEGRITY_MISMATCH: 'INTEGRITY_MISMATCH',
38	  POLICY_INVALID: 'POLICY_INVALID',
39	  POLICY_VIOLATION: 'POLICY_VIOLATION',
40	  USAGE_ERROR: 'USAGE_ERROR',
41	});
42	
43	class ProvError extends Error {
44	  constructor(code, message, details) {
45	    super(message);
46	    this.name = 'ProvError';
47	    this.code = code;
48	    if (details !== undefined) this.details = details;
49	  }
50	}
51	
52	// 把 Node 底层错误归类为 INPUT_NOT_FOUND / PERMISSION_DENIED，其余原样抛出。
53	function wrapFsError(err, context) {
54	  if (err instanceof ProvError) return err;
55	  const where = context ? `${context}: ` : '';
56	  if (err && err.code === 'ENOENT') {
57	    return new ProvError(ERROR_CODES.INPUT_NOT_FOUND, `${where}路径不存在 (${err.path || 'unknown path'})`);
58	  }
59	  if (err && (err.code === 'EACCES' || err.code === 'EPERM')) {
60	    return new ProvError(ERROR_CODES.PERMISSION_DENIED, `${where}权限不足 (${err.path || 'unknown path'})`);
61	  }
62	  return err;
63	}
64	
65	// ---------------------------------------------------------------------------
66	// 路径与摘要工具
67	// ---------------------------------------------------------------------------
68	
69	// 清单中的相对路径统一使用正斜杠，保证跨平台稳定。
70	export function toPosix(relPath) {
71	  return relPath.split(sep).join('/');
72	}
73	
74	// 稳定哈希：SHA-256，摘要对象按 key 排序后以 UTF-8 序列化（两空格缩进）。
75	export function stableJsonStringify(value) {
76	  return JSON.stringify(sortDeep(value), null, 2);
77	}
78	
79	function sortDeep(value) {
80	  if (Array.isArray(value)) return value.map(sortDeep);
81	  if (value !== null && typeof value === 'object') {
82	    const out = {};
83	    for (const key of Object.keys(value).sort()) out[key] = sortDeep(value[key]);
84	    return out;
85	  }
86	  return value;
87	}
88	
89	export function sha256Hex(data) {
90	  return createHash('sha256').update(data).digest('hex');
91	}
92	
93	// 公钥指纹：对 SPKI 编码的 DER 字节取 SHA-256。写入证明并随证明一起签名，
94	// 验证时据此区分“使用了错误公钥”（指纹不一致）与“签名内容被篡改”（指纹一致但验签失败）。
95	export function keyFingerprint(keyObj) {
96	  return sha256Hex(keyObj.export({ type: 'spki', format: 'der' }));
97	}
98	
99	// ---------------------------------------------------------------------------
100	// 产物扫描：递归列出全部常规文件（含符号链接解引用后的目标），
101	// 空目录自然产生空清单；零字节文件按真实文件记录。
102	// ---------------------------------------------------------------------------
103	
104	async function walkFiles(rootDir) {
105	  const found = [];
106	  async function walk(dir) {
107	    let entries;
108	    try {
109	      entries = await readdir(dir, { withFileTypes: true });
110	    } catch (err) {
111	      throw wrapFsError(err, '读取产物目录');
112	    }
113	    for (const entry of entries) {
114	      const full = join(dir, entry.name);
115	      if (entry.isDirectory()) {
116	        await walk(full);
117	      } else if (entry.isFile()) {
118	        found.push(full);
119	      } else if (entry.isSymbolicLink()) {
120	        // 解引用后按目标类型处理：指向目录则继续递归，指向文件则记录。
121	        let target;
122	        try {
123	          target = await stat(full);
124	        } catch (err) {
125	          throw wrapFsError(err, '读取符号链接');
126	        }
127	        if (target.isDirectory()) await walk(full);
128	        else if (target.isFile()) found.push(full);
129	      }
130	      // 其他特殊文件（套接字/设备等）忽略。
131	    }
132	  }
133	  await walk(rootDir);
134	  return found;
135	}
136	
137	// 判断 root 是否位于 outDir 之内（用于从扫描结果排除输出目录自身）。
138	function isWithin(pathAbs, dirAbs) {
139	  const relPath = relative(dirAbs, pathAbs);
140	  return relPath === '' || (!!relPath && !relPath.startsWith('..') && !isAbsolute(relPath));
141	}
142	
143	async function fileTypeFromPath(fullPath, data) {
144	  // 极简魔数嗅探，仅用于清单的 type 字段；不识别时回退为扩展名或 "data"。
145	  // 一律使用字节数组，避免多字节字符串经 UTF-8 编码后长度/取值不符。
146	  const startsWith = (bytes) =>
147	    data.length >= bytes.length && bytes.every((b, i) => data[i] === b);
148	  if (startsWith([0x1f, 0x8b])) return 'application/gzip';
149	  if (startsWith([0x50, 0x4b, 0x03, 0x04])) return 'application/zip';
150	  if (startsWith([0x25, 0x50, 0x44, 0x46, 0x2d])) return 'application/pdf'; // %PDF-
151	  if (startsWith([0x7f, 0x45, 0x4c, 0x46])) return 'application/x-elf';
152	  if (startsWith([0x4d, 0x5a])) return 'application/x-dosexec'; // MZ
153	  if (startsWith([0xff, 0xd8, 0xff])) return 'image/jpeg';
154	  if (startsWith([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a])) return 'image/png';
155	  // 类脚本/文本：UTF BOM，或前 512 字节不含 NUL 则视为 text。
156	  if (
157	    startsWith([0xef, 0xbb, 0xbf]) ||
158	    startsWith([0xff, 0xfe]) ||
159	    startsWith([0xfe, 0xff])
160	  ) {
161	    return 'text/plain';
162	  }
163	  if (!data.subarray(0, 512).includes(0)) return 'text/plain';
164	  const ext = basename(fullPath).split('.').pop();
165	  return ext && ext !== basename(fullPath) ? `application/x-${ext.toLowerCase()}` : 'application/octet-stream';
166	}
167	
168	// 构建 SBOM。时间字段不进入清单，文件摘要只依赖文件字节与相对路径。
169	// excludeDir 为输出目录的绝对路径（若位于产物内部则排除）。
170	export async function buildSbom(artifactPath, excludeDir) {
171	  const artifactAbs = resolve(artifactPath);
172	  let artifactStat;
173	  try {
174	    artifactStat = await stat(artifactAbs);
175	  } catch (err) {
176	    throw wrapFsError(err, '读取产物');
177	  }
178	
179	  const rootDir = artifactStat.isDirectory() ? artifactAbs : dirname(artifactAbs);
180	  const excludeAbs = excludeDir ? resolve(excludeDir) : null;
181	
182	  let files;
183	  if (artifactStat.isDirectory()) {
184	    files = await walkFiles(artifactAbs);
185	  } else {
186	    files = [artifactAbs];
187	  }
188	
189	  const entries = [];
190	  for (const full of files) {
191	    if (excludeAbs && isWithin(full, excludeAbs)) continue;
192	    let data;
193	    try {
194	      data = await readFile(full);
195	    } catch (err) {
196	      throw wrapFsError(err, '读取产物文件');
197	    }
198	    const relPath = toPosix(relative(rootDir, full));
199	    entries.push({
200	      path: relPath,
201	      sha256: sha256Hex(data),
202	      size: data.length,
203	      type: await fileTypeFromPath(full, data),
204	    });
205	  }
206	
207	  // 按相对路径排序，保证同一输入产生字节级一致的清单。
208	  entries.sort((a, b) => (a.path < b.path ? -1 : a.path > b.path ? 1 : 0));
209	
210	  return {
211	    schemaVersion: '1.0',
212	    artifactName: artifactStat.isDirectory() ? basename(artifactAbs) : basename(artifactAbs),
213	    rootType: artifactStat.isDirectory() ? 'directory' : 'file',
214	    files: entries,
215	  };
216	}
217	
218	// 顶层产物摘要：对“排序后的文件条目列表”做稳定哈希。
219	// 任何字节变化、文件新增/删除/重命名都会改变该摘要。
220	export function computeArtifactDigest(sbom) {
221	  return sha256Hex(stableJsonStringify(sbom.files));
222	}
223	
224	// ---------------------------------------------------------------------------
225	// 密钥与签名（Ed25519，PEM）
226	// ---------------------------------------------------------------------------
227	
228	function readPrivateKey(keyPath) {
229	  let pem;
230	  try {
231	    pem = readFileSync(keyPath);
232	  } catch (err) {
233	    throw wrapFsError(err, '读取私钥');
234	  }
235	  let keyObj;
236	  try {
237	    keyObj = createPrivateKey({ key: pem, format: 'pem' });
238	  } catch {
239	    throw new ProvError(ERROR_CODES.KEY_NOT_FOUND, `私钥无法解析或格式不受支持: ${keyPath}`);
240	  }
241	  if (keyObj.asymmetricKeyType !== 'ed25519') {
242	    throw new ProvError(
243	      ERROR_CODES.KEY_NOT_FOUND,
244	      `私钥类型不是 Ed25519（实际为 ${keyObj.asymmetricKeyType}）: ${keyPath}`,
245	    );
246	  }
247	  return keyObj;
248	}
249	
250	function readPublicKey(keyPath) {
251	  let pem;
252	  try {
253	    pem = readFileSync(keyPath);
254	  } catch (err) {
255	    throw wrapFsError(err, '读取公钥');
256	  }
257	  let keyObj;
258	  try {
259	    keyObj = createPublicKey({ key: pem, format: 'pem' });
260	  } catch {
261	    throw new ProvError(ERROR_CODES.KEY_NOT_FOUND, `公钥无法解析或格式不受支持: ${keyPath}`);
262	  }
263	  if (keyObj.asymmetricKeyType !== 'ed25519') {
264	    throw new ProvError(
265	      ERROR_CODES.KEY_NOT_FOUND,
266	      `公钥类型不是 Ed25519（实际为 ${keyObj.asymmetricKeyType}）: ${keyPath}`,
267	    );
268	  }
269	  return keyObj;
270	}
271	
272	// 生成阶段时间戳采用 UTC ISO-8601；它只写入 proof，不参与任何摘要。
273	function nowIso() {
274	  return new Date().toISOString();
275	}
276	
277	// ---------------------------------------------------------------------------
278	// keygen
279	// ---------------------------------------------------------------------------
280	
281	export async function keygen({ keyDir, name = 'provguard' }) {
282	  const absDir = resolve(keyDir);
283	  try {
284	    await mkdir(absDir, { recursive: true });
285	  } catch (err) {
286	    throw wrapFsError(err, '创建密钥目录');
287	  }
288	  const { publicKey, privateKey } = generateKeyPairSync('ed25519');
289	  const privPath = join(absDir, `${name}.private.pem`);
290	  const pubPath = join(absDir, `${name}.public.pem`);
291	  try {
292	    await writeFile(
293	      privPath,
294	      privateKey.export({ type: 'pkcs8', format: 'pem' }),
295	      { mode: 0o600 },
296	    );
297	    await writeFile(
298	      pubPath,
299	      publicKey.export({ type: 'spki', format: 'pem' }),
300	      { mode: 0o644 },
301	    );
302	  } catch (err) {
303	    throw wrapFsError(err, '写入密钥');
304	  }
305	  return { privateKeyPath: privPath, publicKeyPath: pubPath };
306	}
307	
308	// ---------------------------------------------------------------------------
309	// generate
310	// ---------------------------------------------------------------------------
311	
312	export async function generate({ artifact, key, out }) {
313	  // 输入检查：产物与私钥必须存在且可读。
314	  const artifactAbs = resolve(artifact);
315	  const keyAbs = resolve(key);
316	  for (const [p, label] of [
317	    [artifactAbs, '产物'],
318	    [keyAbs, '私钥'],
319	  ]) {
320	    try {
321	      await access(p, fsConstants.R_OK);
322	    } catch (err) {
323	      throw wrapFsError(err, `读取${label}`);
324	    }
325	  }
326	
327	  const outAbs = resolve(out);
328	  const parent = dirname(outAbs);
329	  try {
330	    await mkdir(parent, { recursive: true });
331	  } catch (err) {
332	    throw wrapFsError(err, '创建输出目录');
333	  }
334	
335	  // 若输出目录尚不存在，先按真实路径创建，再据此排除。
336	  try {
337	    await mkdir(outAbs, { recursive: true });
338	  } catch (err) {
339	    throw wrapFsError(err, '创建输出目录');
340	  }
341	  let outReal;
342	  try {
343	    outReal = await realpath(outAbs);
344	  } catch (err) {
345	    throw wrapFsError(err, '解析输出目录');
346	  }
347	
348	  const privateKey = readPrivateKey(keyAbs);
349	  // 由私钥导出对应公钥，记录其指纹到证明中，供验证区分错误公钥与签名失配。
350	  const signingPublicKey = createPublicKey(privateKey);
351	  const signerKeyFingerprint = keyFingerprint(signingPublicKey);
352	
353	  const sbom = await buildSbom(artifactAbs, outReal);
354	  const artifactDigest = computeArtifactDigest(sbom);
355	
356	  // SBOM 规范字节：稳定 JSON（去尾换行后的 UTF-8）。proof 中的 sbomDigest 与
357	  // sbom.json.sig 绑定同一组字节，防止证明有效而 sbom.json 被整体替换。
358	  const sbomCanonical = stableJsonStringify(sbom);
359	  const sbomDigest = sha256Hex(sbomCanonical);
360	
361	  const proof = {
362	    proofVersion: PROOF_VERSION,
363	    artifactName: basename(artifactAbs),
364	    artifactDigest,
365	    fileName: basename(artifactAbs),
366	    size: sbom.files.reduce((n, f) => n + f.size, 0),
367	    generatedAt: nowIso(),
368	    signerKeyFingerprint,
369	    sbomDigest,
370	    files: sbom.files,
371	  };
372	  // 稳定字段顺序：proof 先按既定顺序构造，再整体排序输出。
373	  const proofJson = stableJsonStringify(proof) + '\n';
374	  const sbomJson = sbomCanonical + '\n';
375	
376	  // 对证明的规范字节（不含尾部换行）签名，验证时使用同一规范形式。
377	  // Ed25519 为纯签名算法，不接受摘要算法参数，故用 sign(null, data, key)。
378	  const signature = cryptoSign(null, Buffer.from(proofJson.trimEnd(), 'utf8'), privateKey);
379	  const signatureB64 = signature.toString('base64') + '\n';
380	  // 对 SBOM 规范字节单独签名，Base64 加换行保存。
381	  const sbomSignature = cryptoSign(null, Buffer.from(sbomCanonical, 'utf8'), privateKey);
382	  const sbomSignatureB64 = sbomSignature.toString('base64') + '\n';
383	
384	  const proofPath = join(outReal, 'proof.json');
385	  const sbomPath = join(outReal, 'sbom.json');
386	  const sigPath = join(outReal, 'proof.json.sig');
387	  const sbomSigPath = join(outReal, 'sbom.json.sig');
388	  try {
389	    await atomicWrite(proofPath, proofJson);
390	    await atomicWrite(sbomPath, sbomJson);
391	    await atomicWrite(sigPath, signatureB64);
392	    await atomicWrite(sbomSigPath, sbomSignatureB64);
393	  } catch (err) {
394	    throw wrapFsError(err, '写入证明产物');
395	  }
396	
397	  return {
398	    proofPath,
399	    sbomPath,
400	    signaturePath: sigPath,
401	    sbomSignaturePath: sbomSigPath,
402	    artifactDigest,
403	    sbomDigest,
404	    fileCount: sbom.files.length,
405	    proofVersion: PROOF_VERSION,
406	  };
407	}
408	
409	// 同目录临时文件 + rename，避免半成品证明文件留在输出目录。
410	async function atomicWrite(target, contents) {
411	  const dir = dirname(target);
412	  const tmp = join(dir, `.${basename(target)}.${process.pid}.tmp`);
413	  await writeFile(tmp, contents, { mode: 0o644 });
414	  try {
415	    await rename(tmp, target);
416	  } catch (err) {
417	    await rm(tmp, { force: true });
418	    throw err;
419	  }
420	}
421	
422	// ---------------------------------------------------------------------------
423	// verify
424	// ---------------------------------------------------------------------------
425	
426	export async function verify({
427	  artifact,
428	  proof: proofPath,
429	  signature: sigPath,
430	  key: pubKeyPath,
431	  sbom: sbomPath,
432	  sbomSignature: sbomSigPath,
433	  policy: policyPath,
434	}) {
435	  const artifactAbs = resolve(artifact);
436	  const proofAbs = resolve(proofPath);
437	  const sigAbs = resolve(sigPath);
438	  const keyAbs = resolve(pubKeyPath);
439	
440	  // --sbom 与 --sbom-signature 必须成对出现；只给一者是用法错误。
441	  const sbomMode = sbomPath !== undefined || sbomSigPath !== undefined;
442	  if (sbomMode && (sbomPath === undefined || sbomSigPath === undefined)) {
443	    throw new ProvError(ERROR_CODES.USAGE_ERROR, '--sbom 与 --sbom-signature 必须成对提供');
444	  }
445	  const sbomAbs = sbomMode ? resolve(sbomPath) : null;
446	  const sbomSigAbs = sbomMode ? resolve(sbomSigPath) : null;
447	
448	  // 1) 所有输入必须存在且可读。
449	  const inputs = [
450	    [artifactAbs, '产物'],
451	    [proofAbs, '证明文件'],
452	    [sigAbs, '签名文件'],
453	    [keyAbs, '公钥'],
454	  ];
455	  if (sbomMode) {
456	    inputs.push([sbomAbs, 'SBOM 文件'], [sbomSigAbs, 'SBOM 签名文件']);
457	  }
458	  for (const [p, label] of inputs) {
459	    try {
460	      await access(p, fsConstants.R_OK);
461	    } catch (err) {
462	      throw wrapFsError(err, `读取${label}`);
463	    }
464	  }
465	
466	  // 2) 公钥必须可解析且为 Ed25519 —— 错误/不支持的公钥归 KEY_NOT_FOUND。
467	  const publicKey = readPublicKey(keyAbs);
468	
469	  // 3) 证明文件必须是可解析的 JSON 且结构合法 —— 否则 PROOF_INVALID。
470	  let proofText;
471	  try {
472	    proofText = await readFileUtf8(proofAbs);
473	  } catch (err) {
474	    throw wrapFsError(err, '读取证明文件');
475	  }
476	  let proof;
477	  try {
478	    proof = JSON.parse(proofText);
479	  } catch {
480	    throw new ProvError(ERROR_CODES.PROOF_INVALID, '证明文件不是合法的 JSON');
481	  }
482	  const proofError = validateProof(proof);
483	  if (proofError) {
484	    throw new ProvError(ERROR_CODES.PROOF_INVALID, proofError);
485	  }
486	
487	  // 4) 签名文件必须是合法 Base64 且长度符合 Ed25519（64 字节）—— 否则 PROOF_INVALID。
488	  const sigText = await readFileUtf8(sigAbs);
489	  const sigB64 = sigText.replace(/\s+/g, '');
490	  let sigBuf;
491	  if (!/^[A-Za-z0-9+/]*={0,2}$/.test(sigB64) || sigB64.length === 0) {
492	    throw new ProvError(ERROR_CODES.PROOF_INVALID, '签名文件不是合法的 Base64 内容');
493	  }
494	  try {
495	    sigBuf = Buffer.from(sigB64, 'base64');
496	  } catch {
497	    throw new ProvError(ERROR_CODES.PROOF_INVALID, '签名文件无法解码为字节');
498	  }
499	  if (sigBuf.length !== 64) {
500	    throw new ProvError(
501	      ERROR_CODES.PROOF_INVALID,
502	      `签名长度非法（Ed25519 应为 64 字节，实际 ${sigBuf.length} 字节）`,
503	    );
504	  }
505	
506	  // 5) 重算证明的规范字节并验签。
507	  //    以磁盘上的 proof.json 原样为真，重新序列化其解析结果用于验签；
508	  //    generate 写出的即为稳定规范形式，因此往返一致。
509	  //
510	  //    错误归类（三者互不相同）：
511	  //      - 提供的公钥与证明中记录的签钥指纹不一致  -> KEY_NOT_FOUND（错误公钥）
512	  //      - 公钥一致但签名验证失败                  -> SIGNATURE_INVALID（签名内容不匹配）
513	  //      - 签名文件本身格式非法（前面）            -> PROOF_INVALID
514	  const providedFingerprint = keyFingerprint(publicKey);
