590	// SBOM 校验：结构 -> 摘要 -> 签名 -> 清单一致性。
591	async function verifySbom({ sbomAbs, sbomSigAbs, proof, publicKey }) {
592	  // a) sbom.json 必须是可解析的 JSON 且结构合法 —— 否则 PROOF_INVALID。
593	  const sbomText = await readFileUtf8(sbomAbs);
594	  let sbom;
595	  try {
596	    sbom = JSON.parse(sbomText);
597	  } catch {
598	    throw new ProvError(ERROR_CODES.PROOF_INVALID, 'SBOM 文件不是合法的 JSON');
599	  }
600	  const sbomError = validateSbom(sbom);
601	  if (sbomError) {
602	    throw new ProvError(ERROR_CODES.PROOF_INVALID, sbomError);
603	  }
604	
605	  // b) 证明必须携带合法的 sbomDigest 字段。
606	  if (typeof proof.sbomDigest !== 'string' || !/^[0-9a-f]{64}$/i.test(proof.sbomDigest)) {
607	    throw new ProvError(ERROR_CODES.PROOF_INVALID, '证明缺少合法的 sbomDigest 字段');
608	  }
609	
610	  // c) 重算 SBOM 规范字节摘要并与证明比对 —— 不一致说明 sbom.json 被替换或改动。
611	  const canonicalSbom = stableJsonStringify(sbom);
612	  const recomputed = sha256Hex(canonicalSbom);
613	  if (recomputed.toLowerCase() !== proof.sbomDigest.toLowerCase()) {
614	    throw new ProvError(
615	      ERROR_CODES.INTEGRITY_MISMATCH,
616	      'sbom.json 与证明记录的 sbomDigest 不一致（SBOM 可能被替换）',
617	      { mismatches: [{ path: 'sbom.json', kind: 'content-modified' }] },
618	    );
619	  }
620	
621	  // d) SBOM 签名：合法 Base64 且 64 字节 —— 否则 PROOF_INVALID；验签失败 SIGNATURE_INVALID。
622	  const sigText = await readFileUtf8(sbomSigAbs);
623	  const sigB64 = sigText.replace(/\s+/g, '');
624	  if (!/^[A-Za-z0-9+/]*={0,2}$/.test(sigB64) || sigB64.length === 0) {
625	    throw new ProvError(ERROR_CODES.PROOF_INVALID, 'SBOM 签名文件不是合法的 Base64 内容');
626	  }
627	  const sigBuf = Buffer.from(sigB64, 'base64');
628	  if (sigBuf.length !== 64) {
629	    throw new ProvError(
630	      ERROR_CODES.PROOF_INVALID,
631	      `SBOM 签名长度非法（Ed25519 应为 64 字节，实际 ${sigBuf.length} 字节）`,
632	    );
633	  }
634	  let sigOk = false;
635	  try {
636	    sigOk = cryptoVerify(null, Buffer.from(canonicalSbom, 'utf8'), publicKey, sigBuf);
637	  } catch {
638	    sigOk = false;
639	  }
640	  if (!sigOk) {
641	    throw new ProvError(
642	      ERROR_CODES.SIGNATURE_INVALID,
643	      'SBOM 签名与 sbom.json 内容不匹配（SBOM 可能被改动，或签名已损坏）',
644	    );
645	  }
646	
647	  // e) SBOM 清单与证明清单逐项一致（证明与当前扫描已在前面比对，故三方一致）。
648	  const mismatches = diffSbomAgainstProof(sbom, proof);
649	  if (mismatches.length > 0) {
650	    throw new ProvError(
651	      ERROR_CODES.INTEGRITY_MISMATCH,
652	      `SBOM 与证明清单存在 ${mismatches.length} 处差异`,
653	      { mismatches },
654	    );
655	  }
656	
657	  return recomputed;
658	}
