825	function daysInMonth(year, month) {
826	  // month: 1-12
827	  if (month === 2) {
828	    return year % 4 === 0 && (year % 100 !== 0 || year % 400 === 0) ? 29 : 28;
829	  }
830	  return month === 4 || month === 6 || month === 9 || month === 11 ? 30 : 31;
831	}
