923	
924	  // 时间区间不得倒置；相等（闭区间单点）允许。
925	  if (policy.proofNotBefore !== undefined && policy.proofNotAfter !== undefined) {
926	    if (parseUtcIso(policy.proofNotBefore) > parseUtcIso(policy.proofNotAfter)) {
