100	// ---------------------------------------------------------------------------
101	// 产物扫描：递归列出全部常规文件。
102	// 符号链接安全处理：
103	//   - 指向产物根目录内部的普通文件/目录：按“链接路径”记录目标内容（既有语义）；
104	//   - 链接形成回路（ELOOP，或指向当前递归栈上的祖先目录）：SYMLINK_INVALID / cycle；
105	//   - 链接目标越出产物根目录（含悬空、指向根外）：SYMLINK_INVALID / outside-root。
106	// 一旦命中上述情况立即失败，不继续递归、不读取链接目标内容、不返回部分清单。
107	// 空目录自然产生空清单；零字节文件按真实文件记录。
108	// ---------------------------------------------------------------------------
109	
110	async function walkFiles(rootDir) {
111	  let rootReal;
112	  try {
113	    rootReal = await realpath(rootDir);
114	  } catch (err) {
115	    throw wrapFsError(err, '解析产物目录');
116	  }
117	
118	  const found = [];
119	
120	  function symlinkError(reason, full) {
121	    const relPath = toPosix(relative(rootReal, full));
122	    const detail = relPath && !relPath.startsWith('..') && !isAbsolute(relPath) ? relPath : full;
123	    const message =
124	      reason === 'cycle'
125	        ? `符号链接形成回路: ${detail}`
126	        : `符号链接目标越出产物根目录: ${detail}`;
127	    return new ProvError(ERROR_CODES.SYMLINK_INVALID, message, {
128	      path: detail,
129	      reason,
130	    });
131	  }
132	
133	  // dirStack 为当前递归链上已展开目录的真实路径（含真实目录与经链接展开的
134	  // 目录），用于识别“指回祖先目录”的非 ELOOP 回路（如 sub/link -> ..）。
135	  // 菱形共享（先前已遍历完、但非当前祖先的目录）不属于回路，允许按各自
136	  // 链接路径重复展开。
137	  async function walk(dirPath, dirReal, dirStack) {
138	    let entries;
139	    try {
140	      entries = await readdir(dirPath, { withFileTypes: true });
141	    } catch (err) {
142	      throw wrapFsError(err, '读取产物目录');
143	    }
144	    for (const entry of entries) {
145	      const full = join(dirPath, entry.name);
146	      if (entry.isDirectory()) {
147	        // dirReal 是当前目录的真实路径，其真实子条目的真实路径可直接拼接，
148	        // 无需额外 realpath 系统调用。
149	        await walk(full, join(dirReal, entry.name), [...dirStack, join(dirReal, entry.name)]);
150	      } else if (entry.isFile()) {
151	        found.push(full);
152	      } else if (entry.isSymbolicLink()) {
153	        // 先完整解析链接目标，再决定处理方式；绝不直接读取链接外部内容。
154	        let targetReal;
155	        try {
156	          targetReal = await realpath(full);
157	        } catch (err) {
158	          if (err && err.code === 'ELOOP') throw symlinkError('cycle', full);
159	          // 悬空链接等解析失败沿用既有归类（ENOENT -> INPUT_NOT_FOUND 等），
160	          // 不冒充 SYMLINK_INVALID：只有回路或根目录外链接才产生该错误。
161	          throw wrapFsError(err, '读取符号链接');
162	        }
163	        if (!isWithin(targetReal, rootReal)) {
164	          throw symlinkError('outside-root', full);
165	        }
166	        let target;
167	        try {
168	          target = await stat(targetReal);
169	        } catch (err) {
170	          throw wrapFsError(err, '读取符号链接');
171	        }
172	        if (target.isDirectory()) {
173	          if (dirStack.includes(targetReal)) throw symlinkError('cycle', full);
174	          // 仍以链接路径（full）递归，使其内容按链接相对路径记录。
175	          await walk(full, targetReal, [...dirStack, targetReal]);
176	        } else if (target.isFile()) {
177	          found.push(full);
178	        }
179	        // 链接目标为其他特殊文件（套接字/设备等）忽略，与既有行为一致。
180	      }
181	      // 其他特殊文件（套接字/设备等）忽略。
182	    }
183	  }
184	  await walk(rootReal, rootReal, [rootReal]);
185	  return found;
186	}
187	
188	// 判断 root 是否位于 outDir 之内（用于从扫描结果排除输出目录自身）。
189	function isWithin(pathAbs, dirAbs) {
190	  const relPath = relative(dirAbs, pathAbs);
191	  return relPath === '' || (!!relPath && !relPath.startsWith('..') && !isAbsolute(relPath));
192	}
